// The consent records' retention purge (CONSENT-1 CN-R10; ADR 0019), run on a
// cron trigger by its own Worker (infra/consent.ts). The consent Runtime owns
// what is purged and when; this only calls it. Generated by gq sync.
import { createConsentServer, type ConsentDatabase } from "@getquick/content/consent/server";

interface Env {
  SITE_ID: string;
  CONSENT_DB: ConsentDatabase;
  // gq.ops.json's consent.retentionDays; without it, the Runtime's default.
  CONSENT_RETENTION_DAYS?: string;
}

export default {
  async scheduled(_controller: unknown, env: Env): Promise<void> {
    const consent = createConsentServer({
      siteId: env.SITE_ID,
      bindings: () => env,
      retentionDays: env.CONSENT_RETENTION_DAYS ? Number(env.CONSENT_RETENTION_DAYS) : undefined,
    });
    const { deleted } = await consent.purge();
    console.log(`Consent purge: ${deleted} record(s) past their retention deleted.`);
  },
};
